create unique index if not exists tasks_faction_difficulty_title_unique
  on public.tasks (faction_id, difficulty_level, title);

insert into public.tasks (faction_id, difficulty_level, title, description, estimated_minutes)
select f.id, task_data.difficulty_level, task_data.title, task_data.description, task_data.estimated_minutes
from (values
  ('Altruism', 1, 'Napiši podporno sporočilo', 'Nekomu napiši iskreno sporočilo, v katerem poveš, kaj pri njem ceniš ali kako ga lahko podpreš.', 10),
  ('Altruism', 1, 'Prisluhni brez prekinjanja', 'Deset minut pozorno poslušaj osebo, ki želi govoriti. Ne ponujaj rešitev, razen če te zanje prosi.', 10),
  ('Altruism', 2, 'Pomagaj pri majhnem opravilu', 'Vprašaj nekoga, ali mu lahko olajšaš eno majhno vsakodnevno opravilo, in pomoč ponudi brez pričakovanja povračila.', 20),
  ('Altruism', 2, 'Izrazi konkretno hvaležnost', 'Osebi povej, za katero konkretno dejanje ali lastnost si ji hvaležen_na, in zakaj ti je to veliko pomenilo.', 10),
  ('Altruism', 3, 'Deli uporabno znanje', 'Nekomu pokaži spretnost ali znanje, ki mu lahko koristi. Najprej preveri, ali si želi tvoje pomoči.', 25),
  ('Altruism', 4, 'Pripravi prijazno presenečenje', 'Pripravi majhno, osebno pozornost za nekoga, pri tem pa upoštevaj njegove želje in meje.', 30),
  ('Altruism', 4, 'Pomagaj lokalni skupnosti', 'Najdi varen in zaupanja vreden način za kratko prostovoljsko pomoč v svoji skupnosti.', 45),
  ('Altruism', 5, 'Organiziraj skupno pomoč', 'Zberi majhno skupino in se dogovorite, kako boste skupaj pomagali pri konkretnem opravilu ali dogodku.', 60),
  ('Altruism', 5, 'Pripravi obrok za drugega', 'Z dovoljenjem pripravi ali deli preprost obrok z nekom, ki bi mu to prišlo prav. Upoštevaj alergije in prehranske želje.', 45),
  ('Altruism', 6, 'Podpri novinca v skupini', 'Nekomu, ki se pridružuje novi skupini ali dejavnosti, nameni čas, ga predstavi drugim in mu razloži osnovne informacije.', 40),
  ('Altruism', 6, 'Ponudi uro prostovoljske pomoči', 'Eno uro nameni organizaciji ali skupnostni dejavnosti, ki ji zaupaš in pri kateri se počutiš varno.', 60),
  ('Altruism', 7, 'Uči spretnost v paru', 'Dogovori se z nekom in mu skozi praktično vajo pomagaj osvojiti spretnost, ki jo obvladaš.', 60),
  ('Altruism', 8, 'Načrtuj skupnostno akcijo', 'Načrtuj in izpelji manjšo prostovoljsko akcijo z jasnim ciljem, razdeljenimi nalogami in soglasjem sodelujočih.', 90),
  ('Altruism', 8, 'Vzpostavi redno podporo', 'Z osebo se dogovori za konkreten, obojestransko sprejemljiv način redne pomoči v naslednjih tednih.', 60),
  ('Altruism', 9, 'Poveži ljudi z viri pomoči', 'Razišči preverjene lokalne vire pomoči in jih posreduj osebi ali skupini, ki jih je izrazila potrebo.', 75),
  ('Altruism', 9, 'Mentoriraj pri cilju', 'Z nekom oblikuj dosegljiv cilj, prisluhni njegovim potrebam in mu pomagaj pripraviti prvi korak.', 75),
  ('Altruism', 9, 'Izpelji dobrodelno pobudo', 'V sodelovanju z uveljavljeno organizacijo izvedi majhno pobudo, pri kateri so namen, stroški in uporaba zbranih sredstev pregledni.', 120),
  ('Altruism', 10, 'Vodi skupinski projekt pomoči', 'Vodi večstopenjski projekt pomoči: dogovori se o potrebah, razdeli naloge in po zaključku preveri, ali je bila pomoč koristna.', 150),
  ('Altruism', 10, 'Ustvari načrt vključevanja', 'S skupino pripravi konkreten načrt, ki bo novim ali spregledanim članom olajšal vključitev, nato pridobi njihove povratne informacije.', 120),
  ('Altruism', 10, 'Organiziraj trajno prostovoljstvo', 'Vzpostavi sodelovanje z zaupanja vredno organizacijo in pripravi izvedljiv načrt za redno prostovoljsko dejavnost.', 150),

  ('Intellect', 1, 'Preberi kratek članek', 'Preberi članek o temi, ki je še ne poznaš. Zapiši eno novo dejstvo in eno vprašanje, ki se ti je porodilo.', 15),
  ('Intellect', 1, 'Nauči se pet novih besed', 'Izberi temo in se nauči pet novih strokovnih ali tujih besed. Za vsako napiši primer uporabe.', 15),
  ('Intellect', 2, 'Reši logično uganko', 'Izberi uganko ali miselni izziv, ki ti je nov, in zapiši, kako si prišel_la do rešitve.', 20),
  ('Intellect', 2, 'Preveri eno trditev', 'Izberi zanimivo trditev iz medijev in jo preveri v vsaj enem zanesljivem viru.', 20),
  ('Intellect', 3, 'Razloži pojem s svojimi besedami', 'Nauči se osnov novega pojma in ga razloži tako, da bi ga razumel nekdo brez predznanja.', 25),
  ('Intellect', 4, 'Preberi poglavje knjige', 'Preberi poglavje poljudnoznanstvene ali strokovne knjige in povzemaj tri ključne ideje.', 35),
  ('Intellect', 4, 'Primerjaj dva vira', 'O isti temi preberi dva neodvisna vira. Primerjaj, kje se strinjata in kje se razlikujeta.', 35),
  ('Intellect', 5, 'Opravi uvodno lekcijo', 'Izberi novo spretnost ali področje in opravi eno strukturirano uvodno lekcijo.', 45),
  ('Intellect', 5, 'Napiši povzetek raziskave', 'O izbrani temi preberi več besedil in napiši povzetek z glavnimi ugotovitvami ter odprtimi vprašanji.', 50),
  ('Intellect', 6, 'Sledi kratkemu tečaju', 'Opravi vsaj eno uro kakovostnega spletnega ali knjižničnega tečaja in si zapiši naslednji korak učenja.', 60),
  ('Intellect', 6, 'Razčleni majhen nabor podatkov', 'Izberi javno dostopen nabor podatkov, oblikuj dve vprašanji in zapiši, kaj podatki povedo in česa ne.', 60),
  ('Intellect', 7, 'Reši zahtevnejši problem', 'Izberi problem iz področja, ki ga želiš bolje razumeti. Poskusi vsaj dva pristopa in primerjaj postopek.', 60),
  ('Intellect', 8, 'Izvedi mini raziskavo', 'Oblikuj raziskovalno vprašanje, preveri vsaj tri kakovostne vire in napiši kratek sklep z omejitvami.', 90),
  ('Intellect', 8, 'Ustvari učni projekt', 'Naučeno uporabi v majhnem projektu, na primer modelu, kodi, poskusu ali analizi, in zabeleži postopek.', 120),
  ('Intellect', 9, 'Pripravi vodič za temo', 'Na podlagi preverjenih virov ustvari razumljiv vodič, ki po korakih predstavi zahtevnejšo temo.', 120),
  ('Intellect', 9, 'Primerjaj raziskovalne ugotovitve', 'Primerjaj več raziskav o istem vprašanju. Opiši razlike v metodah, rezultatih in možnih omejitvah.', 120),
  ('Intellect', 9, 'Nauči druge zahtevno idejo', 'Pripravi kratko razlago zahtevnejše ideje, jo predstavi zainteresirani osebi in jo izboljšaj na podlagi vprašanj.', 90),
  ('Intellect', 10, 'Izdelaj samostojen raziskovalni projekt', 'Izvedi projekt od vprašanja do predstavitve: uporabi preverljive vire ali podatke ter jasno navedi omejitve sklepanja.', 180),
  ('Intellect', 10, 'Napiši kritični pregled knjige', 'Preberi zahtevnejšo knjigo s področja, ki ga raziskuješ, in napiši kritični pregled argumentov ter dokazov.', 180),
  ('Intellect', 10, 'Reši odprt izziv', 'Izberi odprt problem, pripravi več možnih rešitev, jih ovrednoti po jasnih merilih in utemelji svojo izbiro.', 150),

  ('Grit', 1, 'Naredi kratko vadbo', 'Izberi varno 10-minutno vadbo, prilagojeno svojim zmožnostim, in si po njej zabeleži, kako si se počutil_a.', 15),
  ('Grit', 1, 'Zaključi odloženo opravilo', 'Izberi majhno opravilo, ki ga odlagaš, in mu nameni 15 minut osredotočenega dela.', 15),
  ('Grit', 2, 'Preizkusi novo spretnost', 'Deset minut vadi spretnost, pri kateri še nisi samozavesten_na. Cilj je vztrajati, ne biti popoln_a.', 15),
  ('Grit', 2, 'Naredi raztezno rutino', 'Opravi nežno 15-minutno raztezanje ali gibljivost, ki ustreza tvojemu telesu. Ob bolečini se ustavi.', 20),
  ('Grit', 3, 'Dokončaj en del projekta', 'Večji projekt razdeli na korake in danes dokončaj en konkreten, dosegljiv del.', 30),
  ('Grit', 4, 'Opravi vadbo za vzdržljivost', 'Opravi 30 minut hoje, kolesarjenja ali druge varne vadbe v tempu, ki ga lahko vzdržuješ.', 40),
  ('Grit', 4, 'Vztrajaj pri zahtevni nalogi', 'Izberi zahtevno nalogo in ji nameni dva 20-minutna bloka z vmesnim kratkim počitkom.', 45),
  ('Grit', 5, 'Preizkusi nov šport', 'Udeleži se začetniške vadbe ali preizkusi nov šport v varnem okolju in z ustrezno opremo.', 60),
  ('Grit', 5, 'Povej svoje mnenje spoštljivo', 'V primernem pogovoru jasno izrazi svoje mnenje, tudi če je drugačno, in ostani odprt_a za odgovor.', 30),
  ('Grit', 6, 'Dokončaj načrtovano vadbo', 'Opravi 45-minutno vadbo, prilagojeno svojim sposobnostim. Načrtuj ogrevanje, počitek in varen zaključek.', 60),
  ('Grit', 6, 'Pojdi na daljši pohod', 'Načrtuj varen pohod približno eno uro, preveri razmere in izberi pot, primerno svoji pripravljenosti.', 75),
  ('Grit', 7, 'Vztrajaj pri ustvarjalnem izzivu', 'Eno uro se posvečaj zahtevnemu ustvarjalnemu ali praktičnemu projektu in dokončaj vnaprej določen korak.', 60),
  ('Grit', 8, 'Izpelji tri vadbene enote', 'V tednu opravi tri varne vadbene enote, prilagojene tvojemu zdravju in pripravljenosti, ter med njimi načrtuj počitek.', 180),
  ('Grit', 8, 'Dokončaj večji osebni projekt', 'Projekt razdeli na vsaj tri korake, razporedi delo čez teden in dokončaj načrtovani rezultat.', 180),
  ('Grit', 9, 'Osvoji zahtevnejšo traso', 'Izberi daljšo, a varno pohodno ali kolesarsko traso, preveri opremo in razmere ter jo opravi v svojem tempu.', 150),
  ('Grit', 9, 'Vadba za moč z načrtom', 'Opravi strukturirano vadbo za moč, prilagojeno svojim zmožnostim. Uporabi pravilno tehniko ali strokovno vodenje.', 75),
  ('Grit', 9, 'Vztrajaj pri novi spretnosti', 'Skozi teden opravi pet kratkih vadbenih enot nove spretnosti in spremljaj napredek, ne popolnosti.', 150),
  ('Grit', 10, 'Sestavi oseben načrt vzdržljivosti', 'Pripravi in izpelji tedenski načrt varne vadbe z jasnimi cilji, počitkom in prilagoditvami glede na počutje.', 210),
  ('Grit', 10, 'Zaključi dolgotrajen izziv', 'Izberi večstopenjski izziv, ki je zate zahteven, a varen, in ta teden dokončaj njegov vnaprej določen zaključni korak.', 180),
  ('Grit', 10, 'Obvladaj zahtevno veščino', 'S pomočjo ustreznih navodil ali mentorja vadi zahtevno veščino in pripravi demonstracijo svojega napredka.', 180),

  ('Verity', 1, 'Preveri spletno trditev', 'Izberi trditev, ki jo vidiš na spletu, in jo preveri v zanesljivem viru, preden jo deliš naprej.', 20),
  ('Verity', 1, 'Zapiši iskren razmislek', 'Zapiši eno stvar, pri kateri si ravnal_a v skladu s svojimi vrednotami, in eno, pri kateri bi želel_a biti bolj iskren_a.', 15),
  ('Verity', 2, 'Priznaj manjšo napako', 'Če je primerno, priznaj majhno napako osebi, ki jo zadeva, in povej, kako jo boš popravil_a.', 15),
  ('Verity', 2, 'Drži dano obljubo', 'Izberi obljubo ali dogovor, ki si ga dal_a, in ga izpolni. Če to ni mogoče, pravočasno povej resnico in predlagaj rešitev.', 20),
  ('Verity', 3, 'Loči dejstvo od mnenja', 'Preberi kratek prispevek in označi, kaj so preverljiva dejstva, kaj razlaga in kaj osebno mnenje.', 25),
  ('Verity', 4, 'Popravi napačno informacijo', 'Če si pred kratkim delil_a napačno informacijo, jo popravi pri istem občinstvu in navedi zanesljiv vir.', 30),
  ('Verity', 4, 'Prisluhni drugačnemu pogledu', 'V pogovoru z osebo, s katero se ne strinjaš, najprej povzemaj njen pogled tako, da ga prepozna kot pravičnega.', 30),
  ('Verity', 5, 'Primerjaj tri vire', 'Trditev o pomembni temi preveri v treh neodvisnih virih in zapiši, kateri dokazi so najmočnejši.', 40),
  ('Verity', 5, 'Povej težko resnico obzirno', 'V varnem in primernem pogovoru iskreno povej pomembno stvar, pri tem pa se osredotoči na dejstva in spoštovanje.', 30),
  ('Verity', 6, 'Preglej svoj argument', 'Zapiši argument, ki mu verjameš. Poišči najmočnejši nasprotni dokaz in pošteno oceni, ali spremeni tvoj sklep.', 50),
  ('Verity', 6, 'Priznaj zasluge sodelavcu', 'Pri skupinskem delu jasno izpostavi prispevek druge osebe in preveri, da je zasluga pripisana pravi osebi.', 25),
  ('Verity', 7, 'Transparentno popravi dogovor', 'Če si pri dogovoru kaj zamolčal_a ali napačno predstavil_a, se vrni k vpletenim osebam in pojasni dejstva ter naslednje korake.', 45),
  ('Verity', 8, 'Napiši uravnotežen pregled teme', 'Razišči zahtevnejšo temo iz več verodostojnih virov. Predstavi dokaze za različne poglede in navedi negotovosti.', 90),
  ('Verity', 8, 'Prevzemi odgovornost za napako', 'Izberi napako, ki je vplivala na druge. Priznaj svoj delež, poslušaj posledice in izvedi dogovorjen popravek.', 60),
  ('Verity', 9, 'Vodi pošten skupinski pogovor', 'Olajšaj razpravo o nesoglasju tako, da imajo vsi možnost govoriti, trditve ostanejo preverljive in dogovori zapisani.', 90),
  ('Verity', 9, 'Preveri lastno pristranskost', 'Pri temi, ki ti je pomembna, poišči kakovostne vire, ki izpodbijajo tvoje predpostavke, in zapiši, kaj si spremenil_a.', 75),
  ('Verity', 9, 'Dokumentiraj odločitev', 'Pri skupinskem projektu zapiši merila, uporabljene informacije, neznanke in razlog za sprejeto odločitev.', 60),
  ('Verity', 10, 'Pripravi raziskovalni pregled', 'Za kompleksno vprašanje primerjaj več kakovostnih virov, loči dokaze od sklepov in pripravi uravnotežen zapis z navedbami.', 150),
  ('Verity', 10, 'Popravi javno napačno trditev', 'Če si javno objavil_a napačno trditev, objavi jasno popravo na istem mestu in pojasni, kaj je bilo narobe.', 45),
  ('Verity', 10, 'Izpelji odgovoren pogovor', 'Pripravi in vodi zahteven, a varen pogovor o nerazrešenem nesoglasju. Povzemi dejstva, potrebe, meje in dogovorjene korake.', 90),

  ('Harmony', 1, 'Meditiraj 5 minut', 'Pet minut sedi v miru in nežno vračaj pozornost k dihu, kadar ti misli odtavajo.', 5),
  ('Harmony', 1, 'Sprehod brez ozadja', 'Deset minut se sprehajaj brez glasbe ali podcasta. Poslušaj zvoke okolice in jih poimenuj.', 10),
  ('Harmony', 2, 'Opiši občutek ob pesmi', 'Poslušaj pesem, ki je še ne poznaš. Z barvami, risbo ali besedami opiši občutke, ki ti jih je vzbudila.', 20),
  ('Harmony', 2, 'Vadi dihanje 10 minut', 'Deset minut počasi in udobno dihaj. Izberi ritem, ki ti ustreza, in se ustavi, če ti postane neprijetno.', 10),
  ('Harmony', 3, 'Preberi 10 strani', 'Preberi deset strani knjige za osebno rast in izberi eno idejo, ki jo želiš preizkusiti.', 20),
  ('Harmony', 4, 'Meditiraj 20 minut', 'Dvajset minut nameni meditaciji v udobnem položaju. Če ti je lažje, uporabi nežno vodeno vajo.', 20),
  ('Harmony', 4, 'Sprehod v naravi', 'Eno uro se sprehajaj brez glasbe ali podcasta. Opazuj okolico in izberi pot, primerno vremenu in tvoji pripravljenosti.', 60),
  ('Harmony', 5, 'Spoznaj zdravilno zelišče', 'Razišči eno zdravilno zelišče v zanesljivem viru. Zapiši, za kaj se tradicionalno uporablja in kakšna so varnostna opozorila.', 35),
  ('Harmony', 5, 'Posadi svojo rastlino', 'Izberi rastlino, primerno prostoru, ki ga imaš, in jo posadi ali posej. Zapiši, kakšno nego potrebuje.', 40),
  ('Harmony', 6, 'Vadi dihanje 15 minut', 'Petnajst minut vadi počasno, sproščeno dihanje. Ne zadržuj diha in vajo prilagodi svojemu počutju.', 15),
  ('Harmony', 6, 'Poslušaj celoten album', 'Poslušaj cel album, ki ga še ne poznaš. Z barvami, risbo ali besedami opiši občutke, ki ti jih je vzbudil.', 50),
  ('Harmony', 7, 'Preberi 50 strani', 'Preberi petdeset strani knjige za osebno rast in zapiši tri misli, ki jih želiš odnesti s sabo.', 90),
  ('Harmony', 8, 'Meditiraj eno uro', 'Meditiraj do ene ure, po potrebi v več krajših sklopih s premori. Izberi način, ki ti omogoča udobje in zbranost.', 60),
  ('Harmony', 8, 'Opravi uro joge', 'Opravi uro joge na ravni, ki ti ustreza. Izogibaj se položajem, ki povzročajo bolečino, in uporabi prilagoditve.', 60),
  ('Harmony', 8, 'Skvačkaj nov izdelek', 'S kvačko in volno izdelaj manjši uporaben ali okrasni izdelek. Delo lahko razdeliš na več krajših sklopov.', 120),
  ('Harmony', 9, 'Začni svoj vrt', 'Razišči osnove vrtnarjenja za svoj prostor, izberi rastlino in pripravi prvi korak za lasten vrt ali zasaditev v posodi.', 90),
  ('Harmony', 9, 'Vadi dihanje 20 minut', 'Dvajset minut izvajaj umirjeno dihalno vajo, ki ti ustreza. Dihaj naravno in se ustavi, če občutiš omotico ali nelagodje.', 20),
  ('Harmony', 9, 'Naslikaj sliko', 'Naslikaj sliko, navdihnjeno z naravo ali svojim trenutnim počutjem. Osredotoči se na proces, ne na popoln rezultat.', 90),
  ('Harmony', 10, 'Nauči se nove pesmi', 'Na inštrument po izbiri se nauči novo pesem. Vadi po delih, načrtuj premore in ob koncu zabeleži napredek.', 120),
  ('Harmony', 10, 'Preberi knjigo za osebno rast', 'Preberi knjigo za osebno rast in pripravi kratek povzetek idej, ki jih želiš premišljeno vključiti v vsakdan.', 240)
) as task_data(faction_name, difficulty_level, title, description, estimated_minutes)
join public.factions f on f.name = task_data.faction_name
on conflict (faction_id, difficulty_level, title) do update
  set description = excluded.description,
      estimated_minutes = excluded.estimated_minutes,
      is_active = true;
